def transform(grid):
    H = len(grid)
    W = len(grid[0]) if H > 0 else 0
    new_H = H * 3
    new_W = W * 2

    output = [[0] * new_W for _ in range(new_H)]

    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            start_row = r * 3
            start_col = c * 2

            for i in range(3):
                for j in range(2):
                    output[start_row + i][start_col + j] = val

    return output
